// In utils/summarizer.ts
import { Task } from '../models/task';

export function generateSummary(tasks: Task[]): Summary {
  const byStatus = tasks.reduce((acc, t) => ({ ...acc, [t.status]: (acc[t.status] || 0) + 1 }), {});
  // Similar reductions for byPriority, tagsSummary, etc.
  const recentEvents = tasks.slice(-5).map(t => ({ id: t.id, status: t.status, timestamp: t.createdAt.toISOString() }));
  const avgTime = tasks.filter(t => t.status === 'completed' && t.completedAt).reduce((sum, t) => sum + (t.completedAt!.getTime() - t.createdAt.getTime()), 0) / (tasks.filter(t => t.completedAt).length || 1);
  return { totalTasks: tasks.length, byStatus, byPriority: {}, recentEvents, averageCompletionTime: avgTime / 1000, tagsSummary: {} };
}

// In index.ts
program
  .command('summarize')
  .option('--output <path>', 'Output file path')
  .action(async (options) => {
    const tasks = await loadTasks(options.config || './tasks.json');
    const summary = generateSummary(tasks);
    console.log(JSON.stringify(summary, null, 2));
    if (options.output) await Bun.write(options.output, JSON.stringify(summary));
  });
```

